    {
      "offset": 27,
      "meaning": "RF context channel identifier; 0xff selects the wildcard/special path"
    },
    {
      "offset": 28,
      "meaning": "RF context byte indexing the 1320-byte RF band table"
    },
    {
      "offset": 29,
